Hier ist eine C++-Funktion, die einen std::string mit Markdown-formatiertem Text akzeptiert und einen std::string mit HTML-formatiertem Text zurückgibt:

```cpp
#include <iostream>
#include <string>
#include <regex>

// Function to convert Markdown to HTML
std::string convertMarkdownToHtml(const std::string& markdown) {
    // Define Markdown patterns and replacements
    const std::regex header_pattern(R"(^(#{1,6})\s(.*)$)", std::regex::case_insensitive);
    const std::string header_replacement("<h$1>$2</h$1>");

    const std::regex bold_pattern(R"( *\*\*([^*]*)\*\*) ");
    const std::string bold_replacement("<strong>$1</strong> ");

    const std::regex italic_pattern(R"( *\*([^*]*)\*) ");
    const std::string italic_replacement("<em>$1</em> ");

    const std::regex link_pattern(R"( *\[(.*?)\]\((.*?)\)) ");
    const std::string link_replacement("<a href=\"$2\">$1</a> ");

    const std::regex inline_code_pattern(R"( *\`([^`]*)\` )");
    const std::string inline_code_replacement("<code>$1</code> ");

    // Define HTML patterns and replacements
    const std::regex paragraph_pattern(R"(^([^#\*\[\`]+[^\n]*)\n?)");
    const std::string paragraph_replacement("<p>$1</p>");

    // Apply replacements
    std::string html = markdown;
    html = std::regex_replace(html, header_pattern, header_replacement, std::regex::format_first_only);
    html = std::regex_replace(html, bold_pattern, bold_replacement, std::regex::format_first_only);
    html = std::regex_replace(html, italic_pattern, italic_replacement, std::regex::format_first_only);
    html = std::regex_replace(html, link_pattern, link_replacement, std::regex::format_first_only);
    html = std::regex_replace(html, inline_code_pattern, inline_code_replacement, std::regex::format_first_only);
    html = std::regex_replace(html, paragraph_pattern, paragraph_replacement, std::regex::format_all);

    return html;
}

int main() {
    std::string markdown = "## Heading\n\nSome **bold** and _italic_ text. \n\n[Link](https://example.com) and `inline code`.";

    std::string html = convertMarkdownToHtml(markdown);

    std::cout << html << std::endl;

    return 0;
}
```

Die Funktion `convertMarkdownToHtml` nimmt einen String mit Markdown-Formatierung als Eingabe und erzeugt einen String mit HTML-Formatierung als Rückgabe. Die Funktion verwendet Reguläre Ausdrücke und String-Replikation, um die verschiedenen Markdown-Elemente in HTML zu konvertieren.

Das Beispiel oben konvertiert den folgenden Markdown-String:

```
## Heading

Some **bold** and _italic_ text.

[Link](https://example.com) and `inline code`.
```

in den folgenden HTML-String:

```
<h2>Heading</h2>

<p>Some <strong>bold</strong> and <em>italic</em> text.</p>

<a href="https://example.com">Link</a> and <code>inline code</code>.
```

